ALTER TABLE public.public_issues ADD COLUMN news_id uuid REFERENCES public.news(id);
CREATE OR REPLACE FUNCTION public.civic_news(_key text,_title text,_body text,_city text,_location uuid,_organization uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE eid uuid; nid uuid; BEGIN INSERT INTO public.events(event_key,title,description,news_body,city_id,starts_at,scope,category,importance,source_id,location_id,organization_id,target_kind) VALUES('civic:'||_key,_title,_body,_body,_city,public.game_now(),'local','Vie locale',85,CASE _city WHEN 'lyon' THEN 'journal-lyon' WHEN 'lille' THEN 'tribune-nord' ELSE 'civitas-matin' END,_location,_organization,'city') ON CONFLICT(event_key) DO NOTHING; SELECT id INTO eid FROM public.events WHERE event_key='civic:'||_key; nid:=public.publish_world_event(eid); RETURN nid; END $$;
REVOKE ALL ON FUNCTION public.civic_news(text,text,text,text,uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.civic_news(text,text,text,text,uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.apply_civic_decision() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status='applied' AND NEW.applied_at IS NULL THEN IF NEW.consequences ? 'project' THEN UPDATE public.locations SET civic_project=NEW.consequences->>'project' WHERE id=NEW.location_id AND city_id=NEW.city_id; END IF; IF NEW.consequences ? 'state' THEN UPDATE public.locations SET civic_state=NEW.consequences->>'state' WHERE id=NEW.location_id AND city_id=NEW.city_id; END IF; NEW.applied_at:=public.game_now(); NEW.news_id:=public.civic_news('decision:'||NEW.id,NEW.title,NEW.description,NEW.city_id,NEW.location_id); END IF; RETURN NEW; END $$;
CREATE TRIGGER civic_decision_consequences BEFORE INSERT OR UPDATE OF status ON public.public_decisions FOR EACH ROW EXECUTE FUNCTION public.apply_civic_decision(); REVOKE ALL ON FUNCTION public.apply_civic_decision() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.refresh_civic_city(_city text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE i public.public_issues; co public.consultations; opt public.consultation_options; target integer; step integer; state_name text; msg text; nid uuid; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended('civic:'||_city,0));
FOR i IN SELECT * FROM public.public_issues WHERE city_id=_city AND status<>'resolved' ORDER BY id FOR UPDATE LOOP target:=LEAST(4,GREATEST(0,floor(extract(epoch FROM(public.game_now()-i.appeared_at))/(i.stage_hours*3600))::integer)); IF target>i.stage THEN FOR step IN i.stage+1..target LOOP state_name:=CASE step WHEN 1 THEN 'identified' WHEN 2 THEN 'studying' WHEN 3 THEN 'ongoing' ELSE 'resolved' END; msg:=CASE step WHEN 1 THEN 'Le service confirme le problème.' WHEN 2 THEN 'Une solution est à l’étude.' WHEN 3 THEN 'L’intervention municipale a commencé.' ELSE 'L’intervention est terminée, le problème est résolu.' END; UPDATE public.public_issues SET stage=step,status=state_name WHERE id=i.id; INSERT INTO public.issue_history(issue_id,status,description,occurred_at) VALUES(i.id,state_name,msg,i.appeared_at+step*i.stage_hours*interval '1 hour') ON CONFLICT DO NOTHING;
IF step=3 THEN INSERT INTO public.public_decisions(decision_key,institution_id,city_id,district_id,location_id,issue_id,title,description,consequences) VALUES('issue:'||i.id,i.institution_id,i.city_id,i.district_id,i.location_id,i.id,'Intervention — '||i.title,'Le service municipal lance une intervention. Le lieu reste accessible pendant les travaux.',jsonb_build_object('state','travaux','project','Intervention : '||i.category)) ON CONFLICT(decision_key) DO NOTHING; END IF;
IF step=4 THEN UPDATE public.locations SET civic_state='renove',civic_project='Intervention achevée : '||i.category WHERE id=i.location_id; nid:=public.civic_news('resolved:'||i.id,'Problème résolu — '||i.title,msg,i.city_id,i.location_id); UPDATE public.public_issues SET news_id=nid WHERE id=i.id; END IF;
INSERT INTO public.notifications(user_id,title,body,world_at) SELECT c.user_id,'Évolution de votre signalement',i.title||' : '||msg,public.game_now() FROM public.citizen_reports r JOIN public.characters c ON c.id=r.character_id LEFT JOIN public.user_settings s ON s.user_id=c.user_id WHERE r.issue_id=i.id AND COALESCE(s.notifications_enabled,true);
END LOOP; END IF; END LOOP;
FOR co IN SELECT * FROM public.consultations WHERE city_id=_city AND status='open' AND ends_at<=public.game_now() ORDER BY id FOR UPDATE LOOP UPDATE public.consultations SET status='closed',closed_at=public.game_now() WHERE id=co.id; SELECT o.* INTO opt FROM public.consultation_options o JOIN public.consultation_participations p ON p.option_id=o.id WHERE o.consultation_id=co.id GROUP BY o.id ORDER BY count(*) DESC,o.sort_order,o.id LIMIT 1; IF FOUND THEN INSERT INTO public.public_decisions(decision_key,institution_id,city_id,district_id,location_id,consultation_id,issue_id,title,description,consequences) VALUES('consultation:'||co.id,co.institution_id,co.city_id,co.district_id,co.location_id,co.id,co.issue_id,'Projet retenu : '||opt.label,'À la suite de la consultation « '||co.title||' », la mairie retient : '||opt.label||'. '||opt.consequence,jsonb_build_object('project',opt.label,'state','projet')) ON CONFLICT(decision_key) DO NOTHING; END IF;
INSERT INTO public.notifications(user_id,title,body,world_at) SELECT c.user_id,'Consultation terminée',co.title,public.game_now() FROM public.consultation_participations p JOIN public.characters c ON c.id=p.character_id LEFT JOIN public.user_settings s ON s.user_id=c.user_id WHERE p.consultation_id=co.id AND COALESCE(s.notifications_enabled,true);
END LOOP; END $$;
REVOKE ALL ON FUNCTION public.refresh_civic_city(text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.refresh_civic_city(text) TO service_role;
CREATE OR REPLACE FUNCTION public.civic_state() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.characters; result jsonb; BEGIN c:=public.civic_actor(); PERFORM public.refresh_civic_city(c.city_id);
SELECT jsonb_build_object('world_now',public.game_now(),'city_id',c.city_id,'city_name',(SELECT name FROM public.cities WHERE id=c.city_id),'engagement',(SELECT engagement FROM public.civic_stats WHERE character_id=c.id),'settings',(SELECT to_jsonb(s) FROM public.civic_settings s WHERE id=1),
'counts',jsonb_build_object('consultations',(SELECT count(*) FROM public.consultation_participations WHERE character_id=c.id),'reports',(SELECT count(*) FROM public.citizen_reports WHERE character_id=c.id),'events',(SELECT count(*) FROM public.civic_rewards WHERE character_id=c.id AND kind='event'),'organizations',(SELECT count(*) FROM public.memberships m JOIN public.organizations o ON o.id=m.organization_id WHERE m.character_id=c.id AND m.status='active' AND o.kind='citizen')),
'institutions',COALESCE((SELECT jsonb_agg(to_jsonb(i)||jsonb_build_object('location',to_jsonb(l))) FROM public.institutions i JOIN public.locations l ON l.id=i.location_id WHERE i.city_id=c.city_id AND i.status='active' AND i.visibility='public'),'[]'::jsonb),
'issues',COALESCE((SELECT jsonb_agg(to_jsonb(i)||jsonb_build_object('location',to_jsonb(l),'district_name',d.name,'institution_name',inst.name,'history',COALESCE((SELECT jsonb_agg(h ORDER BY h.occurred_at) FROM public.issue_history h WHERE h.issue_id=i.id),'[]'::jsonb)) ORDER BY i.appeared_at DESC) FROM public.public_issues i JOIN public.locations l ON l.id=i.location_id JOIN public.districts d ON d.id=i.district_id JOIN public.institutions inst ON inst.id=i.institution_id WHERE i.city_id=c.city_id),'[]'::jsonb),
'reports',COALESCE((SELECT jsonb_agg(r ORDER BY r.created_at DESC) FROM public.citizen_reports r WHERE r.character_id=c.id),'[]'::jsonb),
'consultations',COALESCE((SELECT jsonb_agg(to_jsonb(co)||jsonb_build_object('institution_name',(SELECT name FROM public.institutions WHERE id=co.institution_id),'participant_count',(SELECT count(*) FROM public.consultation_participations p WHERE p.consultation_id=co.id),'my_option_id',(SELECT option_id FROM public.consultation_participations p WHERE p.character_id=c.id AND p.consultation_id=co.id),'options',COALESCE((SELECT jsonb_agg(to_jsonb(o)||jsonb_build_object('votes',CASE WHEN co.status='closed' THEN (SELECT count(*) FROM public.consultation_participations p WHERE p.option_id=o.id) ELSE NULL END) ORDER BY o.sort_order) FROM public.consultation_options o WHERE o.consultation_id=co.id),'[]'::jsonb)) ORDER BY co.starts_at DESC) FROM public.consultations co WHERE co.city_id=c.city_id),'[]'::jsonb),
'decisions',COALESCE((SELECT jsonb_agg(to_jsonb(d)||jsonb_build_object('location',to_jsonb(l),'institution_name',i.name) ORDER BY d.decided_at DESC) FROM public.public_decisions d JOIN public.locations l ON l.id=d.location_id JOIN public.institutions i ON i.id=d.institution_id WHERE d.city_id=c.city_id),'[]'::jsonb),
'events',COALESCE((SELECT jsonb_agg(to_jsonb(e)||jsonb_build_object('organization_name',o.name,'location',to_jsonb(l),'member',EXISTS(SELECT 1 FROM public.memberships m WHERE m.character_id=c.id AND m.organization_id=o.id AND m.status='active'),'activity',(SELECT to_jsonb(a) FROM public.activities a WHERE a.character_id=c.id AND a.organization_event_id=e.id AND a.status IN('planned','running') AND a.end_time>public.game_now() ORDER BY a.start_time LIMIT 1))) FROM public.organization_events e JOIN public.organizations o ON o.id=e.organization_id JOIN public.locations l ON l.id=e.location_id WHERE e.civic AND e.status='active' AND o.city_id=c.city_id),'[]'::jsonb)) INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.civic_state() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.civic_state() TO authenticated;
INSERT INTO public.civic_settings(id) VALUES(1);
INSERT INTO public.institutions(city_id,institution_key,name,type,description,location_id,role,address,opening_hours) SELECT c.id,c.id||':mairie','Mairie de '||c.name,'Mairie','La maison commune des habitants de '||c.name||'. Administration fictive de CIVITAS.',l.id,'Coordonner les services, écouter les habitants et décider des projets locaux.','1, place de la Cité — '||c.name,'Lundi–vendredi, 09:00–17:00 (fictifs)' FROM public.cities c JOIN public.locations l ON l.city_id=c.id AND l.kind='mairie';
INSERT INTO public.institutions(city_id,institution_key,name,type,description,location_id,role,address,opening_hours,parent_id,responsible) SELECT c.id,c.id||':'||v.key,v.name||' de '||c.name,v.type,v.description,l.id,v.role,'Quartier municipal — '||c.name,'Lundi–vendredi, 09:00–17:00 (fictifs)',m.id,'Camille Martin — responsable fictif' FROM public.cities c JOIN public.institutions m ON m.institution_key=c.id||':mairie' CROSS JOIN (VALUES('service','Services municipaux','Service municipal','Voirie, propreté, éclairage, espaces verts et sport.','Entretenir les espaces et traiter les signalements.','administration'),('universite','Université publique','Université publique','Jeunesse, études et logement étudiant.','Accompagner la vie étudiante.','universite'),('transport','Service de transport','Service de transport','Déplacements locaux et information voyageurs.','Organiser les déplacements publics.','station'),('culture','Service culturel','Service culturel','Bibliothèques et rencontres culturelles.','Soutenir la culture locale.','culture'),('social','Service social','Service social','Accueil, solidarité et accès au logement.','Orienter les habitants vers les services.','administration'),('administratif','Accueil administratif','Service administratif','Démarches fictives et renseignements municipaux.','Informer et orienter les citoyens.','mairie')) v(key,name,type,description,role,kind) JOIN public.locations l ON l.city_id=c.id AND l.kind=v.kind;
INSERT INTO public.public_issues(issue_key,institution_id,city_id,district_id,location_id,title,description,category,stage_hours) SELECT c.id||':initial',i.id,c.id,l.district_id,l.id,CASE c.id WHEN 'lyon' THEN 'Éclairage insuffisant sur la place' WHEN 'lille' THEN 'Équipement sportif à entretenir' WHEN 'marseille' THEN 'Propreté de la place centrale' WHEN 'bordeaux' THEN 'Espace vert à rénover' ELSE 'Revêtement piéton dégradé' END,'Les habitants attendent une intervention du service municipal dans leur quartier.',CASE c.id WHEN 'lyon' THEN 'Éclairage' WHEN 'lille' THEN 'Sport' WHEN 'marseille' THEN 'Propreté' WHEN 'bordeaux' THEN 'Espaces verts' ELSE 'Voirie' END,24 FROM public.cities c JOIN public.institutions i ON i.institution_key=c.id||':service' JOIN public.locations l ON l.city_id=c.id AND l.kind='place';
INSERT INTO public.issue_history(issue_id,status,description) SELECT id,'reported','Situation portée à l’attention du service municipal.' FROM public.public_issues WHERE issue_key IS NOT NULL;
INSERT INTO public.consultations(consultation_key,institution_id,city_id,district_id,location_id,organization_id,issue_id,title,description,starts_at,ends_at) SELECT c.id||':initial',i.id,c.id,l.district_id,l.id,o.id,p.id,CASE c.id WHEN 'lyon' THEN 'Quel projet pour la place de Lyon ?' WHEN 'lille' THEN 'Sport ou culture dans le quartier ?' WHEN 'marseille' THEN 'Comment valoriser la place du quartier ?' WHEN 'bordeaux' THEN 'Quel espace vert pour les habitants ?' ELSE 'Quelle priorité pour la vie de quartier ?' END,'La mairie consulte les habitants. Le choix majoritaire orientera un projet local ; en cas d’égalité, l’ordre des options départage.',public.game_now()-interval '1 hour',public.game_now()+interval '3 days' FROM public.cities c JOIN public.institutions i ON i.institution_key=c.id||':mairie' JOIN public.locations l ON l.city_id=c.id AND l.kind='place' JOIN public.organizations o ON o.city_id=c.id AND o.kind='citizen' LEFT JOIN public.public_issues p ON p.issue_key=c.id||':initial';
INSERT INTO public.consultation_options(consultation_id,label,consequence,sort_order) SELECT co.id,v.label,'Le projet sera visible sur la fiche du lieu dans la carte.',v.n FROM public.consultations co CROSS JOIN (VALUES('Jardin partagé',0),('Terrain sportif',1),('Espace culturel',2)) v(label,n) WHERE co.consultation_key IS NOT NULL;
INSERT INTO public.organization_events(organization_id,title,description,location_id,start_hour,duration_minutes,energy_cost,relation_gain,reputation_gain,influence_gain,institution_id,civic) SELECT o.id,'Forum citoyen de '||c.name,'Rencontre fictive avec les habitants et le service municipal, organisée par l’association citoyenne.',o.location_id,18,60,8,10,2,1,i.id,true FROM public.organizations o JOIN public.cities c ON c.id=o.city_id JOIN public.institutions i ON i.institution_key=c.id||':mairie' WHERE o.kind='citizen';
INSERT INTO public.public_decisions(decision_key,institution_id,city_id,district_id,location_id,title,description,consequences) SELECT c.id||':initial',i.id,c.id,l.district_id,l.id,'Accueil citoyen ouvert à '||c.name,'La mairie ouvre un espace d’information citoyenne. Retrouvez les services et les projets de votre ville.',jsonb_build_object('project','Accueil citoyen','state','accueil') FROM public.cities c JOIN public.institutions i ON i.institution_key=c.id||':mairie' JOIN public.locations l ON l.city_id=c.id AND l.kind='mairie';